create table recommendation_caches
(
    id                     bigint generated by default as identity
        primary key,
    expires_at             timestamp(6) with time zone not null,
    generated_at           timestamp(6) with time zone not null,
    recommendation_score   numeric(38, 2)              not null,
    recommended_product_id bigint                      not null
        constraint fkne9gywpj1uryblli7hf86iacd
            references products,
    user_id                bigint                      not null
        constraint fkifgyjjb7cjato209f1iprtwc5
            references users
);

alter table recommendation_caches
    owner to postgres;

